import { type ReactElement, type ReactNode } from 'react';
import { type AttrState, type Module } from '@divi/types';
export type StyleMode = Module.StyleMode;
export type SelectorFunctionParams<TAttr> = Module.SelectorFunctionParams<TAttr>;
export interface StyleImportantProp {
    [key: string]: boolean;
}
export type SelectorFunction = Module.SelectorFunction;
export type StyleProps<TAttr> = Module.StyleProps<TAttr>;
export interface StyleWrapperProps<TAttr> {
    attr: TAttr;
    children: ReactNode;
    asStyle: boolean;
}
export interface StyleContainerProps {
    children?: ReactElement | ReactElement[];
    mode: StyleMode;
    state: AttrState;
    noStyleTag?: boolean;
    noEmptyStyle?: boolean;
}
